// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        vm.deal(attacker, 1 wei);
        vm.prank(attacker);
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success, "attacker deposit failed");
        assertTrue(c.depositsCount() == 1);
    }
}
